def solve_layering(tgt, stamps, maxd=5):
    colors = ['p','O','W']
    full = [[tgt[u][v] for v in range(10)] for u in range(10)]
    def rec(con, depth, path):
        # con: dict (u,v)->color or None if don't care
        rem = [k for k,c in con.items() if c is not None]
        if not rem or all(con[k]=='W' for k in rem):
            return list(path)
        if depth == 0:
            return None
        # candidate last-pour: stamp region must be monochrome among constrained cells
        cands = []
        for sname,f in stamps.items():
            reg = cells(f)
            for col in colors:
                ok = True; covers = 0
                for (u,v) in reg:
                    c = con[(u,v)]
                    if c is not None:
                        if c != col: ok = False; break
                        covers += 1
                if ok and covers>0:
                    cands.append((covers, sname, col, reg))
        cands.sort(reverse=True)
        for covers, sname, col, reg in cands:
            newcon = dict(con)
            for cell in reg: newcon[cell] = None
            path.append((sname,col))
            res = rec(newcon, depth-1, path)
            if res: return res
            path.pop()
        return None
    con = {(u,v): full[u][v] for u in range(10) for v in range(10)}
    for d in range(1, maxd+1):
        r = rec(con, d, [])
        if r: return d, r
    return None, None
